import Foundation
public actor LocalStore { let root: URL; public init(root: URL? = nil) throws { let base = try root ?? FileManager.default.url(for: .applicationSupportDirectory, in: .userDomainMask, appropriateFor: nil, create: true); self.root = base.appending(path: "drinkr", directoryHint: .isDirectory); try FileManager.default.createDirectory(at: self.root, withIntermediateDirectories: true) }; public func save<T: Encodable>(_ value: T, _ name: String) throws { try JSONEncoder.drinkr.encode(value).write(to: root.appending(path: name), options: .atomic) }; public func load<T: Decodable>(_ type: T.Type, _ name: String) throws -> T? { let file = root.appending(path: name); guard FileManager.default.fileExists(atPath: file.path) else { return nil }; return try JSONDecoder.drinkr.decode(T.self, from: Data(contentsOf: file)) }; public func saveImage(_ data: Data, named name: String) throws -> String { let relative="images/\(name).jpg"; let file=root.appending(path:relative); try FileManager.default.createDirectory(at:file.deletingLastPathComponent(),withIntermediateDirectories:true); try data.write(to:file,options:.atomic); return relative }; public func image(at relative: String) throws -> Data { try Data(contentsOf: root.appending(path:relative)) }; public func remove(_ relative: String) throws { let file=root.appending(path:relative); if FileManager.default.fileExists(atPath:file.path) { try FileManager.default.removeItem(at:file) } } }
public actor DraftOutbox { let store: LocalStore; public init(store: LocalStore) { self.store = store }; public func all() async throws -> [Draft] { try await store.load([Draft].self, "outbox.json") ?? [] }; public func save(_ draft: Draft) async throws { var values = try await all(); values.removeAll { $0.id == draft.id }; values.append(draft); try await store.save(values, "outbox.json") }; public func remove(_ draft: Draft) async throws { var values=try await all(); values.removeAll{$0.id==draft.id}; try await store.save(values,"outbox.json"); try? await store.remove(draft.imagePath) } }
